examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space4) {
    if let formError {
        MonarchInlineNotice(formError, tone: .danger)
    }
    switch step {
    case .request:
        Text("Reset your password").monarchTextStyle(.title).foregroundStyle(theme.colors.textDefault).accessibilityAddTraits(.isHeader)
        Text("Enter the email address of your account and we’ll send you a link to choose a new password.")
            .monarchTextStyle(.bodySmall)
            .foregroundStyle(theme.colors.textMuted)
        MonarchTextField("Email", text: $email, prompt: "", error: emailError, isRequired: true)
            .textContentType(.emailAddress)
            .onSubmit(requestLink)
        MonarchButton("Send reset link", variant: .primary, isLoading: isWorking, fullWidth: true, action: requestLink)
        Button("Back to sign in") {
            // Open the sign-in screen.
        }
        .buttonStyle(.monarchLink(.inline))
        .monarchTextStyle(.bodySmall)
        .frame(maxWidth: .infinity)
    case .sent:
        Text("Check your email").monarchTextStyle(.title).foregroundStyle(theme.colors.textDefault).accessibilityAddTraits(.isHeader)
        Text("If an account exists for \(email), you’ll get an email with a link to reset your password.")
            .monarchTextStyle(.body)
        MonarchButton("Use a different email", variant: .ghost) { step = .request }
    case .reset:
        Text("Choose a new password").monarchTextStyle(.title).foregroundStyle(theme.colors.textDefault).accessibilityAddTraits(.isHeader)
        MonarchPasswordInput("New password", text: $password, purpose: .new)
        MonarchPasswordStrengthMeter(password: password)
        MonarchPasswordInput("Confirm new password", text: $confirmation, error: mismatch, purpose: .new)
        MonarchButton("Change password", variant: .primary, isLoading: isWorking, fullWidth: true, action: changePassword)
            .disabled(!meetsRules || confirmation.isEmpty || mismatch != nil)
    case .done:
        Text("Password changed").monarchTextStyle(.title).foregroundStyle(theme.colors.textDefault).accessibilityAddTraits(.isHeader)
        Text("You can now sign in with your new password.").monarchTextStyle(.body)
        MonarchButton("Back to sign in", variant: .primary, fullWidth: true) { step = .request }
    }
}
.onOpenURL { url in
    // The emailed link opens the app through a Universal Link.
    if url.path == "/reset-password" { step = .reset }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
private enum Step { case request, sent, reset, done }
@State private var step = Step.request
@State private var email = {{email}}
@State private var emailError: String?
@State private var password = ""
@State private var confirmation = ""
@State private var isWorking = false
@State private var formError: String?

private var meetsRules: Bool { MonarchPasswordRule.defaults.allSatisfy { $0.test(password) } }
private var mismatch: String? {
    confirmation.isEmpty || confirmation == password ? nil : "The passwords don’t match."
}

private func requestLink() {
    guard email.contains("@"), email.contains(".") else {
        emailError = "Enter an email address like name@example.com."
        return
    }
    emailError = nil
    isWorking = true
    Task {
        // The app's request. A thrown error goes in formError.
        try? await Task.sleep(for: .milliseconds(300))
        isWorking = false
        step = .sent
    }
}

private func changePassword() {
    guard meetsRules, mismatch == nil, !confirmation.isEmpty else { return }
    isWorking = true
    Task {
        // The app saves the password with the token from the link.
        try? await Task.sleep(for: .milliseconds(300))
        isWorking = false
        step = .done
    }
}

